from __future__ import annotations

import asyncio
import hashlib
import os
import tempfile
import uuid
from pathlib import Path

from paperdb.storage.base import StorageBackend, StoredObject, content_key


class LocalStorage(StorageBackend):
    name = "local"

    def __init__(self, root: Path) -> None:
        self.root = root

    def _path(self, key: str) -> Path:
        # Keys are generated by content_key(); reject anything path-like anyway.
        if key.startswith("/") or ".." in Path(key).parts:
            raise ValueError("invalid storage key")
        return self.root / key

    async def put_bytes(self, data: bytes, *, extension: str = "pdf") -> StoredObject:
        digest = hashlib.sha256(data).hexdigest()
        key = content_key(digest, extension)
        target = self._path(key)
        await asyncio.to_thread(self._write_atomic, target, data)
        return StoredObject(backend=self.name, key=key, sha256=digest, byte_size=len(data))

    def _write_atomic(self, target: Path, data: bytes) -> None:
        target.parent.mkdir(parents=True, exist_ok=True)
        fd, tmp = tempfile.mkstemp(prefix=".tmp-", dir=target.parent)
        try:
            with os.fdopen(fd, "wb") as handle:
                handle.write(data)
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(tmp, target)
        finally:
            if os.path.exists(tmp):
                os.unlink(tmp)

    async def read_bytes(self, key: str) -> bytes:
        return await asyncio.to_thread(self._path(key).read_bytes)

    async def exists(self, key: str) -> bool:
        return await asyncio.to_thread(self._path(key).is_file)

    async def size(self, key: str) -> int:
        return await asyncio.to_thread(lambda: self._path(key).stat().st_size)

    async def read_range(self, key: str, start: int, end: int) -> bytes:
        def read() -> bytes:
            with self._path(key).open("rb") as handle:
                handle.seek(start)
                return handle.read(end - start + 1)

        return await asyncio.to_thread(read)

    async def delete(self, key: str) -> None:
        try:
            await asyncio.to_thread(self._path(key).unlink)
        except FileNotFoundError:
            return

    async def healthcheck(self) -> None:
        probe = self.root / f".health-{uuid.uuid4().hex}"
        try:
            await asyncio.to_thread(self.root.mkdir, parents=True, exist_ok=True)
            await asyncio.to_thread(probe.write_bytes, b"ok")
            payload = await asyncio.to_thread(probe.read_bytes)
            if payload != b"ok":
                raise RuntimeError("storage healthcheck read mismatch")
        finally:
            if probe.exists():
                await asyncio.to_thread(probe.unlink)
